import org.slf4j.MDC;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import java.util.*;

public class ObservabilityDemo {
    private static final Logger log = LoggerFactory.getLogger(ObservabilityDemo.class);
    private static final Map<String, Long> counters = new HashMap<>();

    static void processSpell(String requestId, String spellName) {
        MDC.put("requestId", requestId);
        try {
            log.info("Processing spell: {}", spellName);
            System.out.println("requestId=" + requestId + " Processing spell: " + spellName);
        } finally {
            MDC.clear();
        }
    }

    static void increment(String metric) {
        counters.merge(metric, 1L, Long::sum);
    }

    static long timeMs(Runnable task) {
        long start = System.currentTimeMillis();
        task.run();
        return System.currentTimeMillis() - start;
    }

    public static void main(String[] args) {
        processSpell("req-001", "Fireball");
        increment("spells.cast");
        increment("spells.cast");
        increment("spells.cast");
        System.out.println("spells.cast = " + counters.get("spells.cast"));
        long ms = timeMs(() -> { try { Thread.sleep(50); } catch (InterruptedException e) {} });
        System.out.println("duration: " + ms + "ms");
    }
}

