import java.util.*;

public class MetricsDashboard {
    long totalRequests = 0;
    long errorRequests = 0;
    List<Long> latenciesMs = new ArrayList<>();

    void recordRequest(long latencyMs, boolean error) {
        totalRequests++;
        if (error) errorRequests++;
        latenciesMs.add(latencyMs);
    }

    double errorRate() {
        if (totalRequests == 0) return 0;
        return (double) errorRequests / totalRequests * 100;
    }

    long p99LatencyMs() {
        List<Long> sorted = new ArrayList<>(latenciesMs);
        Collections.sort(sorted);
        int idx = (int) Math.ceil(sorted.size() * 0.99) - 1;
        return sorted.get(Math.max(0, idx));
    }

    public static void main(String[] args) {
        MetricsDashboard d = new MetricsDashboard();
        Random rng = new Random(42);
        for (int i = 0; i < 97; i++) d.recordRequest(10 + rng.nextInt(190), i < 5);
        d.recordRequest(900, false); d.recordRequest(900, false); d.recordRequest(900, false);
        System.out.println("Rate: " + d.totalRequests + " requests");
        System.out.printf("Error rate: %.1f%%%n", d.errorRate());
        System.out.println("p99 latency: " + d.p99LatencyMs() + "ms");
    }
}
